let managedRoom=sessionStorage.getItem('village-managed-room')||'',campusBoard=null,campusLoading=false;
const baseCampusTeacherRequest=request;request=async function(url,body,auth=token){if(managedRoom&&!['/api/join','/api/create'].includes(url)){if(body)body={...body,managedRoom};else url+=(url.includes('?')?'&':'?')+'classroom='+encodeURIComponent(managedRoom)}return baseCampusTeacherRequest(url,body,auth)};
const baseCampusTeacherShow=show;show=function(d,force=false){if(el('#teacherStory').dataset.room!==d.room.id){el('#teacherStory').innerHTML='';el('#teacherStory').dataset.room=d.room.id}baseCampusTeacherShow(d,force);refreshCampusTeacher()};
async function refreshCampusTeacher(){if(!token||campusLoading)return;campusLoading=true;try{campusBoard=await request('/api/campus');drawCampusTeacher()}catch(e){el('#campusFeedback').textContent=e.message}finally{campusLoading=false}}
function drawCampusTeacher(){const d=campusBoard,selector=el('#managedClass');if(document.activeElement!==selector){selector.innerHTML=d.rooms.map(r=>`<option value="${r.id}">${esc(r.label)} · ${r.students}명 · ${r.code}</option>`).join('');selector.value=d.home}if(!el('#campusEdit').contains(document.activeElement)){el('#classLabel').value=d.rooms.find(r=>r.id===d.home)?.label||'';el('#travelOpen').checked=d.travel;el('#libraryOpen').checked=d.library}el('#campusOverview').innerHTML=d.rooms.map(r=>`<span><b>${esc(r.label)}</b>${r.students}명 · ${r.code}</span>`).join('');el('#studyRoster').innerHTML=d.records.length?'<table><thead><tr><th>학생</th><th>목표</th><th>기록 시간</th><th>마무리</th><th>포인트</th></tr></thead><tbody>'+d.records.map(s=>`<tr><td>${esc(s.name)}<small style="display:block">${esc(s.accountName)}</small></td><td>${esc(s.goal)}</td><td>${Math.floor((s.status==='finished'?s.reported:s.elapsed)/60)}분 · ${s.status==='finished'?'마침':s.status==='cancelled'?'보상 없이 종료':s.status==='paused'?'휴식':'진행'}</td><td>${esc(s.reflection)}</td><td>${s.points}P</td></tr>`).join('')+'</tbody></table>':'<p>이 학급의 공부 기록이 아직 없어요.</p>'}
el('#managedClass').onchange=async()=>{const old=managedRoom;managedRoom=el('#managedClass').value;sessionStorage.setItem('village-managed-room',managedRoom);try{editing=false;show(await request('/api/state'),true);el('#campusFeedback').textContent='선택한 학급의 기록과 운영 화면으로 전환했어요.'}catch(e){managedRoom=old;sessionStorage.setItem('village-managed-room',old);el('#campusFeedback').textContent=e.message}};
el('#linkClass').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{campusBoard=await request('/api/campus/link',{code:el('#linkRoomCode').value,teacherKey:el('#linkTeacherCode').value,label:el('#linkLabel').value,homeLabel:el('#classLabel').value});el('#linkTeacherCode').value='';drawCampusTeacher();el('#campusFeedback').textContent='학급을 연결했어요.'}catch(e){el('#campusFeedback').textContent=e.message}finally{button.disabled=false}};
el('#campusEdit').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{campusBoard=await request('/api/campus/settings',{label:el('#classLabel').value,travel:el('#travelOpen').checked,library:el('#libraryOpen').checked});drawCampusTeacher();el('#campusFeedback').textContent='마을 이름과 학교 운영 설정을 저장했어요. 여행·별빛도서관 개방은 연결된 모든 반에 적용돼요.'}catch(e){el('#campusFeedback').textContent=e.message}finally{button.disabled=false}};
el('#exportStudy').onclick=()=>{if(!campusBoard)return;csv('별빛도서관-학생기록.csv',[['학생 번호','별명','목표','시작','상태','기록된 집중 분','학생 마무리','포인트'],...campusBoard.records.map(s=>[s.accountName,s.name,s.goal,new Date(s.created).toLocaleString('ko-KR'),s.status,Math.floor((s.status==='finished'?s.reported:s.elapsed)/60),s.reflection,s.points])])};

if(token)request('/api/state').then(d=>{if(!d.teacher)throw Error('교사 코드가 아닙니다.');show(d,true)}).catch(()=>{token='';sessionStorage.removeItem('village-teacher-token')});

const seatAdmin=document.createElement('section');seatAdmin.className='teacher-card';seatAdmin.innerHTML='<h2>선택한 공부방 좌석</h2><p>휴식 중에는 자리를 유지합니다. 연결이 15분 이상 끊긴 자리는 자동 반환됩니다. 필요한 경우 교사가 자리를 반환할 수 있으며 공부 기록은 남습니다.</p><div id="teacherSeats"></div>';el('#teacherCampus').after(seatAdmin);const originalCampusDraw=drawCampusTeacher;drawCampusTeacher=function(){originalCampusDraw();const seats=(campusBoard.seats||[]).filter(s=>s.studyRoom===campusBoard.home);el('#teacherSeats').innerHTML='<p><b>'+seats.length+' / 30석</b> 사용 중</p>'+seats.map(s=>`<div class="teacher-row"><span>${s.number}번 · ${esc(s.name)} · ${esc(s.status)}</span><button data-release-desk="${s.number}">자리 반환</button></div>`).join('')};seatAdmin.onclick=async e=>{const b=e.target.closest('[data-release-desk]');if(!b)return;const n=Number(b.dataset.releaseDesk);if(!confirm(n+'번 자리를 반환할까요? 학생의 집중은 쉬는 상태가 되고 기록은 유지됩니다.'))return;b.disabled=true;try{campusBoard=await request('/api/campus/seats/release',{number:n});drawCampusTeacher()}catch(error){el('#campusFeedback').textContent=error.message;b.disabled=false}};
